function g(r,a){const f=r.filter(([n,t])=>Number.isFinite(n)&&Number.isFinite(t)).map(([n,t])=>[Math.max(0,Math.min(n,t)),Math.max(0,Math.max(n,t))]).sort((n,t)=>n[0]-t[0]),o=[];for(const n of f){const t=o[o.length-1];t&&n[0]<=t[1]?t[1]=Math.max(t[1],n[1]):o.push([n[0],n[1]])}const c=[],i=[];let e=0,u=null;const s=[];for(const[n,t]of o){if(u!==null&&n-u>20){const l=e+u;c.push({dStart:l,dEnd:l+3,skipped:n-u-3}),e+=3-(n-u)}s.push({realStart:n,dStart:n+e,realEnd:t,dEnd:t+e}),i.push([n+e,t+e]),u=t}const h=a+e;return{map:n=>{for(let t=0;t<o.length;t++){const[l,m]=o[t];if(n<=m)return n<=l?s[t].dStart:n+(s[t].dStart-l);if(t+1<o.length&&n<o[t+1][0]){const M=s[t].dEnd,_=(n-m)/(o[t+1][0]-m);return M+_*3}}return n+e},unmap:n=>{for(const t of s){if(n>=t.dStart&&n<=t.dEnd)return t.realStart+(n-t.dStart);if(n<t.dStart)return t.realStart}return a},total:h,gaps:c,segments:i}}const S=[1,2,5,10,30,60,120,300,600,1800,3600,7200,14400,43200],$=56;function E(r){if(r<60)return`${Math.round(r)}s`;if(r<3600)return`${Math.floor(r/60)}m${Math.round(r%60)?`${Math.round(r%60)}s`:""}`;const a=Math.floor(r/3600),f=Math.round(r%3600/60);return f?`${a}h${f}m`:`${a}h`}function O(r){if(r<1)return`${Math.round(r*1e3)}ms`;if(r<60)return`${Math.round(r*10)/10}s`;if(r<3600){const o=Math.floor(r/60),c=Math.round(r%60);return c?`${o}m${c}s`:`${o}m`}const a=Math.floor(r/3600),f=Math.round(r%3600/60);return f?`${a}h${f}m`:`${a}h`}function T(r,a,f,o=50,c=0){const i=f-a;if(i<=0)return[];let e=S[S.length-1];for(const s of S)if(!(i/s>o)&&!(c>0&&s/i*c<$)){e=s;break}const u=[];for(const[s,h]of r.segments){if(h<a||s>f)continue;const d=r.unmap(s),p=Math.ceil(d/e)*e;for(let n=p;;n+=e){const t=r.map(n);if(t>h+1e-6)break;if(t>=a-1e-6&&t<=f+1e-6&&u.push({d:t,t:n,label:E(n)}),u.length>200)return u}}return u.sort((s,h)=>s.d-h.d)}export{T as a,g as b,O as f};
